package vendor

import (
	"fmt"
	"os"
	"path/filepath"
	"time"

	"gopkg.in/yaml.v3"
)

// ProvenanceFileName is the marker file written inside vendored skill directories.
const ProvenanceFileName = ".axon-vendor.yaml"

// Provenance tracks the upstream origin and last mirrored state of a vendored skill.
type Provenance struct {
	Vendor   string    `yaml:"vendor"`
	Repo     string    `yaml:"repo"`
	Subdir   string    `yaml:"subdir"`
	Ref      string    `yaml:"ref"`
	Commit   string    `yaml:"commit"`
	SyncedAt time.Time `yaml:"synced_at"`
}

// ProvenancePath returns the absolute path to .axon-vendor.yaml inside destDir.
func ProvenancePath(destDir string) string {
	return filepath.Join(destDir, ProvenanceFileName)
}

// ReadProvenance reads .axon-vendor.yaml from destDir.
// Returns (nil, nil) if the file does not exist.
func ReadProvenance(destDir string) (*Provenance, error) {
	path := ProvenancePath(destDir)
	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, fmt.Errorf("cannot read provenance %s: %w", path, err)
	}

	var p Provenance
	if err := yaml.Unmarshal(data, &p); err != nil {
		return nil, fmt.Errorf("invalid YAML in provenance %s: %w", path, err)
	}
	return &p, nil
}

// WriteProvenance marshals and writes provenance into destDir/.axon-vendor.yaml.
func WriteProvenance(destDir string, p Provenance) error {
	data, err := yaml.Marshal(p)
	if err != nil {
		return fmt.Errorf("cannot marshal provenance: %w", err)
	}

	header := []byte("# Generated by axon vendor. DO NOT EDIT MANUALLY.\n")
	content := append(header, data...)

	path := ProvenancePath(destDir)
	if err := os.WriteFile(path, content, 0o644); err != nil {
		return fmt.Errorf("cannot write provenance %s: %w", path, err)
	}
	return nil
}
